func (r *MutationResolver) RunReport(ctx context.Context, input gqlmodel.RunReportInput) (*gqlmodel.ReportRun, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceReport, permission.OpExport)
	if err != nil {
		return nil, err
	}

	req := &reportingservice.RunReportRequest{
		Request: reportingRequest(authCtx),
		Format:  report.Format(input.Format),
		Params:  input.Params,
		Trigger: report.RunTriggerManual,
	}
	if input.DefinitionID != nil {
		definitionID, parseErr := pulid.MustParse(*input.DefinitionID)
		if parseErr != nil {
			return nil, parseErr
		}
		req.DefinitionID = definitionID
	}
	if input.CannedKey != nil {
		req.CannedKey = *input.CannedKey
	}

	viewRequest, err := r.applyReportView(ctx, authCtx, input.ViewID, req)
	if err != nil {
		return nil, err
	}

	run, err := r.ReportingService.RunReport(ctx, req)
	if err != nil {
		return nil, err
	}

	// Stamped only once the run is actually queued, so a rejected run never
	// inflates a view's usage.
	if viewRequest != nil {
		r.ReportingService.RecordViewRun(ctx, viewRequest)
	}

	return reportRunToModel(run), nil
}

