func (r *QueryResolver) ReportRuns(ctx context.Context, input gqlmodel.DataTableConnectionInput, filter *gqlmodel.ReportRunsFilterInput) (*gqlmodel.ReportRunConnection, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceReport, permission.OpRead)
	if err != nil {
		return nil, err
	}

	tableInput, err := gqlconnection.DataTableConnectionFromGraphQL(ctx, &input, resolvercore.TenantInfo(authCtx))
	if err != nil {
		return nil, err
	}

	req := &reportports.ListReportRunConnectionRequest{
		Filter: tableInput.Filter,
		Cursor: tableInput.Cursor,
	}
	if filter != nil {
		if filter.DefinitionID != nil {
			definitionID, parseErr := pulid.MustParse(*filter.DefinitionID)
			if parseErr != nil {
				return nil, parseErr
			}
			req.DefinitionID = definitionID
		}
		for _, status := range filter.Statuses {
			req.Statuses = append(req.Statuses, report.RunStatus(status))
		}
	}

	result, err := r.ReportingService.ListRunsConnection(ctx, req)
	if err != nil {
		return nil, err
	}

	return reportRunConnectionToModel(result)
}

